      /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}/.test(
        section.creator.updated_at,
      ),
    );
    // Validate deleted_at is null for active sections (soft-delete semantics)
    TestValidator.equals(
