/**
 * Test article tag update with new tag creation.
 *
 * This test validates the tag auto-creation business rule where non-existent tags
 * are automatically created when updating article tags with new tag names.
 *
 * Test Flow:
 * 1. Admin creates a section required for article creation
 * 2. Member creates an article without initial tags
 * 3. Member updates article tags with a new tag name that doesn't exist
 * 4. Verify response contains the newly created tag with correct ID and name
 * 5. Verify the tag can be reused in subsequent operations
 */
export async function test_api_article_tag_update_new_tag_creation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create section
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardAdmin.IJoin,
  });
  typia.assert(adminAuth);
  const section = await generate_random_discussion_board_admin_sections_create(
    adminConnection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 2 }),
      } satisfies IDiscussionBoardSection.ICreate,
    },
  );
  typia.assert(section);
  // 2. Member setup - create article without tags
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      displayName: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(memberAuth);
  const article = await generate_random_discussion_board_member_articles_create(
    memberConnection,
    {
      body: {
        title: RandomGenerator.name(3),
        body: RandomGenerator.content({ paragraphs: 2 }),
        discussion_board_section_id: section.id,
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);
  // 3. Update article tags with a NEW tag name that doesn't exist
  const newTagName =
    RandomGenerator.name(1) + "_" + RandomGenerator.alphabets(5);
  const tagUpdateResponse =
    await api.functional.discussionBoard.member.articles.tags.update(
      memberConnection,
      {
        articleId: article.id,
        body: {
          tags: [newTagName],
        } satisfies IDiscussionBoardArticle.ITag,
      },
    );
  typia.assert(tagUpdateResponse);
  // 4. Verify response contains the newly created tag
  TestValidator.equals(
    "tag name matches input",
    tagUpdateResponse.tag.name,
    newTagName,
  );
  // Verify tag has valid UUID ID
  TestValidator.predicate(
    "tag has valid UUID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      tagUpdateResponse.tag.id,
    ),
  );
  // Verify tag association has valid UUID ID
  TestValidator.predicate(
    "tag association has valid UUID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      tagUpdateResponse.id,
    ),
  );
  // 5. Verify tag can be reused by updating article again with same tag
  const reuseTagName = newTagName;
  const reuseResponse =
    await api.functional.discussionBoard.member.articles.tags.update(
      memberConnection,
      {
        articleId: article.id,
        body: {
          tags: [reuseTagName],
        } satisfies IDiscussionBoardArticle.ITag,
      },
    );
  typia.assert(reuseResponse);
  // Verify reused tag has same ID (not newly created)
  TestValidator.equals(
    "reused tag has same ID",
    reuseResponse.tag.id,
    tagUpdateResponse.tag.id,
  );
}

