  TestValidator.equals(
    "member ID preserved",
    updatedComment.member.id,
    memberAuth.id,
  );
  TestValidator.equals(
    "created_at unchanged",
    updatedComment.created_at,
    comment.created_at,
  );
  TestValidator.predicate(
    "updated_at changed",
    updatedComment.updated_at !== comment.updated_at,
  );
}

