/**
 * Test that an administrator can successfully update a comment on a discussion board article.
 *
 * Workflow:
 * 1. Create admin account and authenticate
 * 2. Create member account and authenticate
 * 3. Create discussion board section as admin
 * 4. Create article as member
 * 5. Create comment on article as member
 * 6. Update the comment as admin
 * 7. Validate: content changed, updated_at changed, created_at unchanged, all fields present
 */
export async function test_api_comment_update_by_admin(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create admin account and authenticate
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardAdmin.IJoin,
  });
  typia.assert(adminAuth);
  // 2. Create member account and authenticate
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      displayName: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IDiscussionBoardMember.IJoin,
  });
  typia.assert(memberAuth);
  // 3. Create discussion board section as admin
  const section = await generate_random_discussion_board_admin_sections_create(
    adminConnection,
    {},
  );
  typia.assert(section);
  // 4. Create article as member
  const article = await generate_random_discussion_board_member_articles_create(
    memberConnection,
    {
      body: {
        discussion_board_section_id: section.id,
        title: RandomGenerator.paragraph({ sentences: 2 }),
        body: RandomGenerator.content({ paragraphs: 3 }),
      } satisfies IDiscussionBoardArticle.ICreate,
    },
  );
  typia.assert(article);
  // 5. Create comment on article as member
  const comment =
    await generate_random_discussion_board_member_articles_comments_create(
      memberConnection,
      {
        params: {
          articleId: article.id,
        },
        body: {
          content: RandomGenerator.paragraph({ sentences: 3 }),
        } satisfies IDiscussionBoardComment.ICreate,
      },
    );
  typia.assert(comment);
  // Store original timestamps
  const originalCreatedAt = comment.created_at;
  const originalUpdatedAt = comment.updated_at;
  // 6. Update the comment as admin
  const updatedContent = RandomGenerator.paragraph({ sentences: 5 });
  const updatedComment =
    await api.functional.discussionBoard.admin.articles.comments.update(
      adminConnection,
      {
        articleId: article.id,
        commentId: comment.id,
        body: {
          content: updatedContent,
        } satisfies IDiscussionBoardComment.IUpdate,
      },
    );
  typia.assert(updatedComment);
  // 7. Validate results
  TestValidator.equals("comment id unchanged", updatedComment.id, comment.id);
  TestValidator.equals(
    "content updated",
    updatedComment.content,
    updatedContent,
  );
  TestValidator.equals(
    "article reference preserved",
    updatedComment.article.id,
    article.id,
  );
  TestValidator.equals(
    "author reference preserved",
    updatedComment.member.id,
    comment.member.id,
  );
  TestValidator.predicate(
    "created_at unchanged",
    updatedComment.created_at === originalCreatedAt,
  );
  TestValidator.predicate(
    "updated_at changed",
    updatedComment.updated_at !== originalUpdatedAt,
  );
  TestValidator.predicate(
    "updated_at is after created_at",
    updatedComment.updated_at >= updatedComment.created_at,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
