      },
      select: {
        tag: {
          select: {
            id: true,
            name: true,
            description: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
          },
        },
      },
    });
  // Transform each tag to summary DTO
  return await ArrayUtil.asyncMap(articleTags, (at) =>
    DiscussionBoardTagAtSummaryTransformer.transform(at.tag),
  );
}

