  const sortBy =
    props.body.sort_by && validSortFields.includes(props.body.sort_by)
      ? props.body.sort_by
      : "created_at";
  const sortOrder = props.body.sort_order === "ASC" ? "ASC" : "DESC";
  const orderByInput: Prisma.discussion_board_adminsOrderByWithRelationInput = {
